#include <png.h>
#include <iostream>
#include <vector>
int main(int argc,char** argv){if(argc!=2)return 1;png_image image{};image.version=PNG_IMAGE_VERSION;if(!png_image_begin_read_from_file(&image,argv[1]))return 2;image.format=PNG_FORMAT_RGBA;std::vector<unsigned char> data(PNG_IMAGE_SIZE(image));if(!png_image_finish_read(&image,nullptr,data.data(),0,nullptr))return 3;unsigned long red=0,green=0,blue=0,opaque=0;for(size_t i=0;i<data.size();i+=4){auto r=data[i],g=data[i+1],b=data[i+2],a=data[i+3];red+=r>200 && g<40 && b<40 && a>200;green+=g>200 && r<40 && b<40 && a>200;blue+=b>200 && r<40 && g<40 && a>200;opaque+=a>200;}std::cout<<"{\"width\":"<<image.width<<",\"height\":"<<image.height<<",\"red\":"<<red<<",\"green\":"<<green<<",\"blue\":"<<blue<<",\"opaque\":"<<opaque<<"}\n";png_image_free(&image);return 0;}
